flow.set("battmaint_rpc_response_topic", msg.rpcResponseTopic);

// Determine operation
let operation = msg.operation || 'read';
const params = msg.rpcParams || {};

// If params has any writable field, it's a write
if (params.batteryControlMode !== undefined ||
    params.wakeUp !== undefined ||
    params.batteryResistanceMilliOhm !== undefined ||
    params.chargeEfficiencyPercent !== undefined) {
    operation = 'write';
}

msg.operation = operation;

if (operation === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("battmaint_part_sn", null);
flow.set("battmaint_part_config", null);

return msg;

msg.readGroup = "sn";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 3,
    quantity: 5
};
return msg;

msg.readGroup = "config";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 211,
    quantity: 4
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for " + msg.readGroup);
    return null;
}

const group = msg.readGroup;

if (group === "sn") {
    flow.set("battmaint_part_sn", data);
} else if (group === "config") {
    flow.set("battmaint_part_config", data);
}

// Check if all parts received
const partSn = flow.get("battmaint_part_sn");
const partConfig = flow.get("battmaint_part_config");

if (!partSn || !partConfig) {
    return null;
}

msg.snData = partSn;
msg.configData = partConfig;
return msg;

const snData = msg.snData;
const configData = msg.configData;

// Clear flow context
flow.set("battmaint_part_sn", null);
flow.set("battmaint_part_config", null);

// Helper: Parse ASCII from packed register
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

// Helper: Parse Serial Number
function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);
        sn += parseAsciiChar(regs[i], false);
    }
    return sn.trim();
}

// Helper: Parse battery control mode
function parseBatteryControlMode(val) {
    switch(val) {
        case 0: return "voltage";
        case 1: return "capacity";
        case 2: return null;
        default: return null;
    }
}

const serialNumber = parseSerialNumber(snData);

const reg211 = configData[0];
const reg212 = configData[1];
const reg213 = configData[2];
const reg214 = configData[3];

const batteryControlMode = parseBatteryControlMode(reg211);
const channel1Enabled = reg212 === 0;
const batteryResistanceMilliOhm = reg213;
const chargeEfficiencyPercent = reg214 * 0.1;

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "BatteryMaintenanceConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: serialNumber,
    version: "1.0",

    batteryControlMode: batteryControlMode,

    wakeUp: {
        channel1Enabled: channel1Enabled,
        channel2Enabled: null
    },

    batteryResistanceMilliOhm: batteryResistanceMilliOhm,
    chargeEfficiencyPercent: Math.round(chargeEfficiencyPercent * 10) / 10
};

// Check if this is after a write
const writeResult = flow.get("battmaint_write_result");
flow.set("battmaint_write_result", null);

const rpcResponseTopic = flow.get("battmaint_rpc_response_topic");
flow.set("battmaint_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Successfully wrote ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const writes = [];

// 211: batteryControlMode
if (params.batteryControlMode !== undefined) {
    let val = 1; // default capacity
    if (params.batteryControlMode === "voltage") val = 0;
    else if (params.batteryControlMode === "capacity") val = 1;
    else if (params.batteryControlMode === null) val = 2;
    writes.push({ register: 211, value: val, name: "Battery Control Mode" });
}

// 212: wakeUp.channel1Enabled
if (params.wakeUp && params.wakeUp.channel1Enabled !== undefined) {
    // 0=enabled, 1=disabled (inverted!)
    const val = params.wakeUp.channel1Enabled ? 0 : 1;
    writes.push({ register: 212, value: val, name: "Wake Up Channel 1" });
}

// 213: batteryResistanceMilliOhm
if (params.batteryResistanceMilliOhm !== undefined) {
    const val = Math.max(0, Math.min(6000, params.batteryResistanceMilliOhm));
    writes.push({ register: 213, value: val, name: "Battery Resistance" });
}

// 214: chargeEfficiencyPercent (0.1% scale)
if (params.chargeEfficiencyPercent !== undefined) {
    // Input is percentage, register is 0.1% scale
    // e.g., 98.5% -> 985
    const val = Math.round(params.chargeEfficiencyPercent * 10);
    const clampedVal = Math.max(0, Math.min(1000, val));
    writes.push({ register: 214, value: clampedVal, name: "Charge Efficiency" });
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    return null;
}

global.set("battmaint_write_queue", writes);
global.set("battmaint_write_index", 0);
global.set("battmaint_write_results", []);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return msg;

const writes = global.get("battmaint_write_queue") || [];
const index = global.get("battmaint_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return msg;

const writes = global.get("battmaint_write_queue") || [];
let index = global.get("battmaint_write_index") || 0;
const results = global.get("battmaint_write_results") || [];

const current = msg.currentWrite;
if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set("battmaint_write_results", results);
}

index++;
global.set("battmaint_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done - save results and trigger read
flow.set("battmaint_write_result", {
    count: results.length,
    writes: results
});

global.set("battmaint_write_queue", null);
global.set("battmaint_write_index", null);
global.set("battmaint_write_results", null);

return [null, msg];
